'use strict';
const C=GameCore,D=C.D,$=s=>document.querySelector(s),canvas=$('#world'),ctx=canvas.getContext('2d');
const SAVE='planet-expedition-v1';let storageOK=true,state;
try{state=C.normalize(JSON.parse(localStorage.getItem(SAVE)));}catch{state=C.fresh();storageOK=false;}
let scene=C.world(state.planet),player={...state.position,vx:0,vy:0,face:1,swing:0},W=0,H=0,scale=30,origin={x:0,y:0},time=0,last=0,started=false,paused=false,panel='',keys=new Set(),stick={x:0,y:0},actionHeld=false,actionCooldown=0,hurtCooldown=0,particles=[],floaters=[],toastTimer=0,uiTimer=0,saveTimer=0,walk=0,audio;
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function costText(cost){return Object.entries(cost).map(([k,v])=>`${v} ${C.name(k)}`).join(' · ');}
function save(){state.position={x:player.x,y:player.y};try{localStorage.setItem(SAVE,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#save-state').textContent=storageOK?'✓ Postup uložený v tomto prehliadači':'Úložisko nedostupné · exportuj uloženie';}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=3.5;}
function sound(freq=500,duration=.1,type='sine'){if(!state.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.6,audio.currentTime+duration);g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function resize(){W=innerWidth;H=innerHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.max(19,Math.min(34,W/38,H/24));origin={x:W*.53,y:H*.53+25};}
addEventListener('resize',resize);resize();
function project(x,y,z=0){let ox=origin.x,oy=origin.y;if(W<700){ox-=(player.x-player.y)*scale*.35;oy-=(player.x+player.y)*scale*.16;}return {x:ox+(x-y)*scale*.8,y:oy+(x+y)*scale*.42-z*scale};}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function ellipse(x,y,rx,ry,color){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();}
function line(a,b,color,width=2){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}
function box(x,y,w,d,h,top,left,right){const a=project(x-w/2,y-d/2,h),b=project(x+w/2,y-d/2,h),c=project(x+w/2,y+d/2,h),e=project(x-w/2,y+d/2,h),cb=project(x+w/2,y+d/2),bb=project(x+w/2,y-d/2),eb=project(x-w/2,y+d/2);poly([b,bb,cb,c],right);poly([e,c,cb,eb],left);poly([a,b,c,e],top);}
function ring(x,y,r,color,width=1){let pts=[];for(let i=0;i<=64;i++){let a=i/64*Math.PI*2;pts.push(project(x+Math.cos(a)*r,y+Math.sin(a)*r,.03));}ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
function label(text,x,y,color='#ebf1da',size=11){ctx.font=`600 ${size}px "Segoe UI",sans-serif`;ctx.textAlign='center';ctx.fillStyle='#071712aa';ctx.fillText(text,x+1,y+2);ctx.fillStyle=color;ctx.fillText(text,x,y);}
function burst(x,y,color,n=10){for(let i=0;i<n;i++)particles.push({x,y,z:.5,vx:(Math.random()-.5)*4,vy:(Math.random()-.5)*4,vz:2+Math.random()*3,life:.5+Math.random()*.5,color});}
function floater(text,x,y,color='#e1f496'){floaters.push({text,x,y,life:1.3,color});}
function drawIsland(){const theme=C.themes[state.planet],rand=C.rng(91+state.planet);const edge=[];for(let i=0;i<64;i++){let a=i/64*Math.PI*2,r=15.8+Math.sin(a*7)*.4;edge.push(project(Math.cos(a)*r,Math.sin(a)*r));}poly(edge.map(p=>({x:p.x,y:p.y+55})),theme[2]);poly(edge,theme[0]);for(let i=0;i<64;i++){const a=edge[i],b=edge[(i+1)%64];if(b.y>a.y&&i<32||i>=0&&i<16)poly([a,b,{x:b.x,y:b.y+55},{x:a.x,y:a.y+55}],i%2?theme[1]:theme[2]);}poly(edge,theme[0]);
for(let i=0;i<420;i++){const x=(rand()-.5)*31,y=(rand()-.5)*31;if(x*x+y*y>235)continue;const p=project(x,y);ctx.globalAlpha=.17+rand()*.15;ellipse(p.x,p.y,rand()*3+1,1,rand()>.4?theme[2]:'#dce5b3');}ctx.globalAlpha=1;
const t=theme[5];if(t!=='ground'){const pts=[];for(let i=0;i<40;i++){let a=i/40*Math.PI*2,r=3.3+Math.sin(a*5)*.25;pts.push(project(-5+Math.cos(a)*r,-1+Math.sin(a)*r,.03));}poly(pts,t==='lava'?'#bd664b':t==='swamp'?'#526c54':'#468e9a');for(let i=0;i<7;i++){let p=project(-7+i*.6,-1+Math.sin(i)*1.4,.05);line({x:p.x-8,y:p.y},{x:p.x+8+Math.sin(time+i)*4,y:p.y},t==='lava'?'#ffbb7b77':'#b0e9db55',1);}}
// Stepping-stone path to the restoration beacon.
for(let i=0;i<8;i++)box(.5,-.2-i*.6,.5,.4,.03,'#bbbea0','#969a7f','#8a9075');
}
function drawNode(n){const p=project(n.x,n.y),s=scale*n.scale,shake=Math.sin(n.shake*50)*n.shake*7;if(n.respawn>0){ellipse(p.x,p.y,s*.22,s*.12,'#34453444');return;}ellipse(p.x+4,p.y+3,s*.6,s*.23,'#122b2538');ctx.save();ctx.translate(shake,0);if(n.type==='Wood'){box(n.x,n.y,.2,.2,1.1,'#a78357','#755c41','#5a4935');const col=state.planet===2?['#a6c3b5','#75a899','#598778']:state.planet===7?['#ac8b91','#8d6979','#6a5369']:['#b4cc78','#82a85c','#5c8548'];for(let j=0;j<3;j++){const q=project(n.x,n.y,1.1+j*.55);const ww=s*(.9-j*.19);poly([{x:q.x-ww,y:q.y},{x:q.x,y:q.y-ww*1.15},{x:q.x+ww,y:q.y},{x:q.x,y:q.y+ww*.3}],col[j]);poly([{x:q.x,y:q.y-ww*1.15},{x:q.x+ww,y:q.y},{x:q.x,y:q.y+ww*.3}],col[Math.min(2,j+1)]);}}else if(n.type==='Rock'){poly([{x:p.x-s*.6,y:p.y},{x:p.x-s*.45,y:p.y-s*.6},{x:p.x+s*.15,y:p.y-s*.85},{x:p.x+s*.6,y:p.y-s*.35},{x:p.x+s*.5,y:p.y+s*.1}], '#a9b9b3');poly([{x:p.x-s*.6,y:p.y},{x:p.x-s*.45,y:p.y-s*.6},{x:p.x,y:p.y-s*.2},{x:p.x+s*.5,y:p.y+s*.1}],'#7c938e');}else{const color=['#89d7d2','#cea7f5','#f2b580'][n.id%3];for(let j=0;j<3;j++){let q=project(n.x+(j-1)*.26,n.y,.1),h=s*(j===1?1.1:.65);poly([{x:q.x-s*.2,y:q.y},{x:q.x-s*.16,y:q.y-h*.7},{x:q.x,y:q.y-h},{x:q.x+s*.2,y:q.y-h*.7},{x:q.x+s*.19,y:q.y}],color);line({x:q.x,y:q.y-h},{x:q.x,y:q.y},'#ffffff66',1);}}ctx.restore();if(n.hp<n.maxHp){ctx.fillStyle='#10271b88';ctx.fillRect(p.x-15,p.y+8,30,3);ctx.fillStyle='#d9f080';ctx.fillRect(p.x-15,p.y+8,30*n.hp/n.maxHp,3);}}
function drawBeacon(){const x=1,y=-3,active=state.restored.includes(state.planet);ring(x,y,1.6,active?'#e5fa9e77':'#d8e9cc44',2);box(x,y,1.8,1.8,.15,'#d1ceb0','#879789','#708477');box(x,y,1,1,.5,'#b1bca7','#637f74','#526e66');const p=project(x,y,1.9+Math.sin(time*1.8)*.08),s=scale*.65;ctx.shadowColor=active?'#e8ff9a':'#9ee7e6';ctx.shadowBlur=active?35:15;poly([{x:p.x,y:p.y-s*1.4},{x:p.x+s*.55,y:p.y},{x:p.x,y:p.y+s*.7},{x:p.x-s*.55,y:p.y}],active?'#e5f8a1':'#a0d9d5');ctx.shadowBlur=0;poly([{x:p.x,y:p.y-s*1.4},{x:p.x,y:p.y+s*.7},{x:p.x-s*.55,y:p.y}],active?'#a6c365':'#61a7aa');const q=project(x,y,3.1);label(active?'OBNOVENÉ':'JADRO PLANÉTY',q.x,q.y,active?'#e4f8a2':'#eaf1d9',9);if(active){ctx.save();ctx.globalAlpha=.15;const g=ctx.createLinearGradient(p.x,p.y,p.x,p.y-240);g.addColorStop(0,'#e7ff8a');g.addColorStop(1,'transparent');poly([{x:p.x-8,y:p.y},{x:p.x+8,y:p.y},{x:p.x+35,y:p.y-240},{x:p.x-35,y:p.y-240}],g);ctx.restore();}}
function drawCamp(){const x=-3,y=4;box(x,y,2,1.6,.2,'#baaa83','#8b7f60','#746d53');box(x,y,1.3,1,1.1,'#ccae7c','#a1875c','#86704e');const a=project(x-1,y-.8,1.15),b=project(x+1,y-.8,1.15),c=project(x+1,y+.8,1.15),d=project(x-1,y+.8,1.15),t=project(x,y-.8,2),u=project(x,y+.8,2);poly([a,t,u,d],'#dcddaf');poly([t,b,c,u],'#959f7b');const p=project(x,y,2.5);label('TÁBOR · E',p.x,p.y,'#edf0d6',9);if(state.home){for(let i=0;i<state.home;i++)box(x-2-i*.5,y,.35,.35,.5,'#e4c78f','#a18b60','#8f7955');}}
function drawCharacter(e,isPlayer=false){if(e.respawn>0)return;const p=project(e.x,e.y),s=scale*(e.boss?1.5:1),bounce=isPlayer?Math.sin(walk*12)*Math.min(.08,Math.hypot(player.vx,player.vy)*.025)*s:Math.sin(time*4+e.x)*2;ellipse(p.x,p.y+2,s*.4,s*.18,'#152d2955');if(isPlayer){const foot=Math.sin(walk*12)*Math.min(5,Math.hypot(player.vx,player.vy));line({x:p.x-5,y:p.y-12},{x:p.x-6+foot,y:p.y},'#34484b',s*.17);line({x:p.x+5,y:p.y-12},{x:p.x+6-foot,y:p.y},'#34484b',s*.17);box(e.x,e.y,.5,.4,.74,'#ebbd78','#c7975c','#a77745');ellipse(p.x,p.y-s*.94+bounce,s*.33,s*.33,'#eadcc4');ellipse(p.x,p.y-s*1.08+bounce,s*.39,s*.28,'#e8eddf');ellipse(p.x+s*.09,p.y-s*.93+bounce,s*.26,s*.16,'#375454');line({x:p.x+s*.02,y:p.y-s*.98+bounce},{x:p.x+s*.2,y:p.y-s*.98+bounce},'#9ed8d6',2);box(e.x-.35,e.y,.23,.42,.52,'#94aaa0','#6e8b83','#546f6a');const swing=player.swing>0?Math.sin(player.swing*12)*1.5:0;const hand={x:p.x+s*.3,y:p.y-s*.43};const end={x:hand.x+Math.cos(-.6+swing)*s*.65,y:hand.y+Math.sin(-.6+swing)*s*.65};line(hand,end,'#b49a6f',4);line({x:end.x-5,y:end.y-5},{x:end.x+5,y:end.y+4},'#e1e4cd',7);if(hurtCooldown>.4&&Math.sin(time*40)>0){ring(e.x,e.y,.7,'#ffac8b',2);}}else{const color=e.hit>0?'#ffddaf':e.boss?'#a96578':'#647f75';ellipse(p.x,p.y-s*.35+bounce,s*.43,s*.46,color);ellipse(p.x-5,p.y-s*.45+bounce,3,3,'#f7d99f');ellipse(p.x+5,p.y-s*.45+bounce,3,3,'#f7d99f');if(e.boss){poly([{x:p.x-10,y:p.y-s*.7},{x:p.x-15,y:p.y-s*1.1},{x:p.x,y:p.y-s*.8},{x:p.x+15,y:p.y-s*1.1},{x:p.x+10,y:p.y-s*.7}],'#d4ba83');}if(e.hp<e.maxHp){ctx.fillStyle='#162b29';ctx.fillRect(p.x-17,p.y-s*.95,34,3);ctx.fillStyle='#efa990';ctx.fillRect(p.x-17,p.y-s*.95,34*e.hp/e.maxHp,3);}if(e.boss)label('STRÁŽCA',p.x,p.y-s*1.3,'#e9c1b5',9);}}
function render(){ctx.clearRect(0,0,W,H);const bg=ctx.createRadialGradient(W*.55,H*.45,30,W*.5,H*.5,W*.7);bg.addColorStop(0,'#294044');bg.addColorStop(1,'#101c24');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);const rand=C.rng(18);for(let i=0;i<100;i++){const x=rand()*W,y=rand()*H;ctx.globalAlpha=.15+Math.sin(time*.5+i)*.12;ellipse(x,y,i%7===0?1.5:.8,i%7===0?1.5:.8,'#e5f1cb');}ctx.globalAlpha=1;let p=project(0,0);ellipse(p.x,p.y+100,scale*15,scale*6,'#06171b66');drawIsland();const objects=[...scene.nodes.map(n=>({depth:n.x+n.y,draw:()=>{ctx.globalAlpha=n.x+n.y>player.x+player.y&&Math.hypot(n.x-player.x,n.y-player.y)<2.8?.45:1;drawNode(n);ctx.globalAlpha=1;}})),...scene.enemies.map(e=>({depth:e.x+e.y,draw:()=>drawCharacter(e)})),{depth:-2,draw:drawBeacon},{depth:1,draw:drawCamp},{depth:player.x+player.y,draw:()=>drawCharacter(player,true)}];objects.sort((a,b)=>a.depth-b.depth).forEach(o=>o.draw());for(const p of particles){const q=project(p.x,p.y,p.z);ctx.globalAlpha=Math.min(1,p.life*2);ellipse(q.x,q.y,2.5,2.5,p.color);}ctx.globalAlpha=1;for(const f of floaters){const q=project(f.x,f.y,1.6+(1.3-f.life));ctx.globalAlpha=Math.min(1,f.life*2);label(f.text,q.x,q.y,f.color,12);}ctx.globalAlpha=1;}
function nearest(){let enemy=scene.enemies.filter(e=>!e.respawn&&Math.hypot(e.x-player.x,e.y-player.y)<2).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(enemy)return {enemy};let node=scene.nodes.filter(n=>!n.respawn&&Math.hypot(n.x-player.x,n.y-player.y)<2.2).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];return node?{node}:null;}
function act(){if(actionCooldown>0)return;actionCooldown=.36;player.swing=.3;const target=nearest();if(!target)return;if(target.enemy){const e=target.enemy,damage=Math.max(3,C.power(state,'sword'))*(1+state.prestige*.1);e.hp-=damage;e.hit=.2;burst(e.x,e.y,'#e8b694',5);floater('−'+Math.round(damage),e.x,e.y,'#ffca9c');sound(170,.12,'triangle');if(e.hp<=0){e.respawn=e.boss?90:30;state.kills++;state.xp+=e.boss?35:7;const coins=e.boss?50+state.planet*15:8+state.planet*3;C.grant(state,'Coin',coins);if(e.boss)C.grant(state,'Diamond',1);notify(e.boss?'Strážca porazený! +'+coins+' mincí a diamant.':'+'+coins+' mincí');}return;}const n=target.node,type=n.type==='Wood'?'axe':'pickaxe',damage=Math.max(1,C.power(state,type));n.hp-=Math.max(1,Math.sqrt(damage));n.shake=.25;const amount=Math.ceil((n.type==='Wood'||n.type==='Rock'?3:1)*(1+state.tools[type]*.15)*(1+state.prestige*.1));C.grant(state,n.type,amount);state.gathered+=amount;state.xp++;C.grant(state,'Coin',1);floater('+'+amount+' '+C.name(n.type),n.x,n.y);burst(n.x,n.y,n.type==='Wood'?'#cce18d':'#b7d9d6',5);sound(n.type==='Wood'?330:700,.065,'triangle');if(n.hp<=0){n.respawn=14;n.hp=n.maxHp;burst(n.x,n.y,'#daebae',14);}updateHUD();}
function interact(){if(Math.hypot(player.x-1,player.y+3)<3.2)openPanel('beacon');else if(Math.hypot(player.x+3,player.y-4)<3)openPanel('home');else notify('Príď k jadru planéty alebo k táboru.');}
function tick(dt){time+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show');}if(!started||paused||panel||document.hidden)return;actionCooldown=Math.max(0,actionCooldown-dt);hurtCooldown=Math.max(0,hurtCooldown-dt);player.swing=Math.max(0,player.swing-dt);let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+stick.x,y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+stick.y;const len=Math.hypot(x,y);if(len>1){x/=len;y/=len;}const terrain=C.terrain(player.x,player.y,state.planet),speed=terrain==='water'?3.5:terrain==='swamp'||terrain==='lava'?3:4;const dx=(x+y)*.707,dy=(y-x)*.707;const damping=1-Math.exp(-15*dt);player.vx+=(dx*speed-player.vx)*damping;player.vy+=(dy*speed-player.vy)*damping;player.x+=player.vx*dt;player.y+=player.vy*dt;walk+=Math.hypot(player.vx,player.vy)*dt;const dist=Math.hypot(player.x,player.y);if(dist>15){player.x*=15/dist;player.y*=15/dist;}if(keys.has(' ')||actionHeld)act();for(const n of scene.nodes){n.respawn=Math.max(0,n.respawn-dt);n.shake=Math.max(0,n.shake-dt);}for(const e of scene.enemies){e.hit=Math.max(0,e.hit-dt);if(e.respawn){e.respawn=Math.max(0,e.respawn-dt);if(!e.respawn)e.hp=e.maxHp;continue;}const dd=Math.hypot(player.x-e.x,player.y-e.y);if(dd<5.2&&dd>.8){e.x+=(player.x-e.x)/dd*dt*(e.boss?.8:1.25);e.y+=(player.y-e.y)/dd*dt*(e.boss?.8:1.25);}if(dd<1.05&&hurtCooldown<=0){state.hp-=Math.max(1,(e.boss?12:5)+state.planet-state.tools.armor*1.5);hurtCooldown=.9;sound(80,.18,'sawtooth');burst(player.x,player.y,'#e89b81');}}if(terrain==='lava'&&hurtCooldown<=0){state.hp-=3;hurtCooldown=1;}if(Math.hypot(player.x+3,player.y-4)<2.5)state.hp=Math.min(100+state.home*20,state.hp+dt*12);if(state.hp<=0){state.hp=100+state.home*20;player.x=-3;player.y=4;state.inventory.Coin=Math.floor(state.inventory.Coin*.9);hurtCooldown=3;notify('Tábor ťa zachránil. Stratil si 10 % mincí.');}for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;p.vz-=9*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);for(const f of floaters)f.life-=dt;floaters=floaters.filter(f=>f.life>0);uiTimer+=dt;saveTimer+=dt;if(uiTimer>.2){uiTimer=0;const done=C.production(state);if(done.length)notify('Výroba dokončená: '+done.map(j=>j.amount+' '+C.name(j.product)).join(', '));updateHUD();}if(saveTimer>5){saveTimer=0;save();}}
function updateHUD(){const p=D.planets[state.planet];$('#wallet').innerHTML=[['Wood','▰'],['Rock','◆'],['Coin','●']].map(([k,i])=>`<div class="currency" title="${C.name(k)}"><i>${i}</i>${Math.floor(state.inventory[k]||0)}</div>`).join('');$('#planet-title').textContent=p.title;$('#planet-number').textContent=String(state.planet+1).padStart(2,'0')+' / 10';$('#biome').textContent=C.themes[state.planet][4];const cost=C.restoreCost(state),restored=state.restored.includes(state.planet),percent=restored?100:Math.min(99,Math.round(Object.entries(cost).reduce((v,[k,n])=>v+Math.min(1,(state.inventory[k]||0)/n),0)/Object.keys(cost).length*100));$('#restoration').textContent=percent+' %';$('#restore-bar').style.width=percent+'%';$('#quest-title').textContent=restored?(state.restored.length===10?'Galaxia opäť žiari':'Vyraz na ďalšiu planétu'):'Rozžiar jadro planéty';$('#quest-detail').textContent=restored?'Otvor hviezdnu mapu a pokračuj vo výprave.':costText(cost);$('#level').textContent='LVL '+(1+Math.floor(state.xp/60));$('#hp-text').textContent=Math.ceil(state.hp);$('#hp-bar').style.width=100*state.hp/(100+state.home*20)+'%';const t=C.terrain(player.x,player.y,state.planet);$('#terrain').textContent=t==='water'?'● Voda · 3.5':t==='lava'?'● Láva · 3.0':t==='swamp'?'● Močiar · 3.0':'● Pevnina · 4.0';let hint='';if(Math.hypot(player.x-1,player.y+3)<3)hint='[E] Jadro planéty · obnova sveta';else if(Math.hypot(player.x+3,player.y-4)<2.7)hint='[E] Tábor · liečenie a domov';else{let n=nearest();if(n)hint=n.enemy?'[SPACE] Útok · '+(n.enemy.boss?'Strážca':'Príšera'):'[SPACE] Zbierať · '+C.name(n.node.type);}$('#target-hint').textContent=hint;}
function heading(k,title,sub){return `<div class="eyebrow">${k}</div><h2>${title}</h2><p class="subtitle">${sub}</p>`;}
function button(text,action,disabled=false,cls='primary'){return `<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;}
function openPanel(id){panel=id;keys.clear();stick={x:0,y:0};actionHeld=false;$('#modal').hidden=false;drawPanel();$('#modal .close').focus();}
function closePanel(){panel='';$('#modal').hidden=true;keys.clear();save();}
function drawPanel(){let html='';if(panel==='map'){html=heading('ATLAS VÝPRAVY','Desať svetov. Jeden domov.','Obnov jadro každej planéty a otvor cestu ďalej. Medzi odomknutými svetmi môžeš voľne cestovať.');html+='<div class="grid">'+D.planets.map((p,i)=>`<article class="card ${i===state.planet?'active':''}"><div class="planet-dot" style="background:${C.themes[i][0]}"></div><span class="eyebrow">PLANÉTA ${String(i+1).padStart(2,'0')}</span><h3 style="margin-top:12px">${p.title}</h3><p>${C.themes[i][4]}</p><span class="badge">${state.restored.includes(i)?'✦ OBNOVENÁ':i<=state.unlocked?'OBJAVENÁ':'UZAMKNUTÁ'}</span>${button(i===state.planet?'Nachádzaš sa tu':i<=state.unlocked?'Cestovať →':'Najprv obnov '+D.planets[i-1].title,'travel:'+i,i>state.unlocked||i===state.planet,i<=state.unlocked?'primary':'')}</article>`).join('')+'</div>';}
if(panel==='inventory'){html=heading('VŠETKO NA SVOJOM MIESTE','Tvoj batoh','Suroviny sa zdieľajú medzi planétami. Zber prebieha pri držaní medzerníka vedľa zdroja.');html+='<div class="grid">'+Object.entries(state.inventory).filter(([k,v])=>v>0||['Wood','Rock','Plank','Steel','Coin'].includes(k)).map(([k,v])=>`<article class="card"><h3>${esc(C.name(k))}</h3><div class="big">${Math.floor(v)}</div>${!['Coin','Wood','Rock','Plank','Steel'].includes(k)?button('Predať 1 ks · +5 mincí','sell:'+k,v<1,''):''}</article>`).join('')+'</div>';}
if(panel==='workshop'){html=heading('LEPŠIE NÁSTROJE, NOVÉ MOŽNOSTI','Dielňa prieskumníka','Sekera a krompáč zrýchlia zber, meč zvýši poškodenie a brnenie ťa ochráni. Ďalšie planéty zvyšujú strop vybavenia.');html+='<div class="grid">'+Object.entries(state.tools).map(([k,l])=>{let cap=k==='armor'?D.planets[state.unlocked].chestplate:D.planets[state.unlocked][k],cost=C.upgradeCost(state,k);return `<article class="card"><span class="badge">ÚROVEŇ ${l} / ${cap}</span><h3 style="margin-top:12px">${C.name(k)}</h3><p>${k==='armor'?'Ochrana': 'Sila nástroja'}: ${k==='armor'?(l*1.5).toFixed(1):C.power(state,k)}</p><p>${l>=cap?'Odomkni ďalšiu planétu.':costText(cost)}</p>${button('Vylepšiť ↑','upgrade:'+k,l>=cap||!C.afford(state,cost))}</article>`;}).join('')+'</div><p class="subtitle" style="margin-top:18px">Hodnoty nástrojov a stropy sú z reportu. Ceny vylepšení sú upravené pre kratšiu HTML5 výpravu; pôvodné recepty nájdeš v dátovom archíve.</p>';}
if(panel==='refinery'){html=heading('ZÁKLAD TVOJEJ VÝROBY','Rafinérie','Zadaj až tri dávky pre každú rafinériu. Výroba pokračuje aj pri zatvorenej hre; hotové suroviny sa pripíšu automaticky.');html+='<div class="grid">'+['Plank','Steel'].map(k=>{const r=C.recipe(k),jobs=state.jobs.filter(j=>j.product===k);return `<article class="card"><span class="badge">${k==='Plank'?'PÍLA':'HUTA'}</span><h3 style="margin-top:12px">${C.name(k)}</h3><div class="big">${state.inventory[k]||0} <small style="font-size:12px">v batohu</small></div><p>${costText(r.cost)} → ${r.amount} ${C.name(k)}<br>${Math.ceil(r.duration*Math.pow(.9825,state.refineryLevel))} sekúnd / dávka</p><div class="notice" data-job="${k}">${jobs.length?jobs.length+' vo fronte · '+Math.max(0,Math.ceil((jobs[0].end-Date.now())/1000))+' s':'Pripravené na výrobu'}</div>${button('Vyrobiť '+r.amount+' ks','craft:'+k,jobs.length>=3||!C.afford(state,r.cost))}</article>`;}).join('')+'</div>';const cost={Coin:1000*(state.refineryLevel+1)};html+=`<div class="row"><span>Efektivita ${state.refineryLevel} · −1,75 % času za úroveň<br><small>${costText(cost)}</small></span>${button('Vylepšiť','refinery-upgrade',!C.afford(state,cost)||state.refineryLevel>=20,'')}</div>`;}
if(panel==='home'){html=heading('MIESTO, KAM SA VRÁTIŤ','Tvoj domov','Tábor lieči, zásoby ostávajú a pomocníci zbierajú. Domov je spoločný pre všetky planéty.');const hc={Plank:10*(state.home+1),Steel:8*(state.home+1)},wc={Coin:100*(state.workers+1),Plank:10};html+=`<div class="grid"><article class="card"><h3>⌂ Tábor · úroveň ${state.home}</h3><p>Každá úroveň pridá 20 maximálnych životov.</p><div class="big">${100+20*state.home} ♥</div><p>${costText(hc)}</p>${button('Rozšíriť domov','build',state.home>=5||!C.afford(state,hc))}</article><article class="card"><h3>⚒ Pomocníci · ${state.workers} / 5</h3><p>Každý prinesie 1 drevo a 1 kameň za 5 sekúnd. Offline zber sa započíta najviac za hodinu.</p><p>${costText(wc)}</p>${button('Prijať pomocníka','worker',state.workers>=5||!C.afford(state,wc))}</article></div><div class="notice" style="margin-top:16px">Príď k stanu na planéte. V jeho blízkosti sa automaticky liečiš.</div>`;}
if(panel==='beacon'){let done=state.restored.includes(state.planet);html=heading('SRDCE PLANÉTY',done?'Tento svet opäť žiari.':'Rozžiar '+D.planets[state.planet].title,done?'Tvoja práca tu zanechala stopu. Vydaj sa k ďalšej hviezde.':'Vlož suroviny do jadra. Obnova ti prinesie mince, skúsenosti a cestu na ďalšiu planétu.');html+=`<div class="card"><div class="big">${done?'✦':'◇'}</div>${done?'<p>Planéta bola obnovená.</p>':Object.entries(C.restoreCost(state)).map(([k,n])=>`<div class="row"><span>${C.name(k)}</span><b style="color:${(state.inventory[k]||0)>=n?'#d9f080':'#eca78d'}">${state.inventory[k]||0} / ${n}</b></div>`).join('')}${button(done?'Otvoriť hviezdnu mapu':'Obnoviť planétu ✦',done?'map':'restore',!done&&!C.afford(state,C.restoreCost(state)))}</div>`;}
if(panel==='journal'){const goal=100*(state.challenge+1);html=heading('KAŽDÁ VÝPRAVA MÁ SVOJ PRÍBEH','Denník výpravy','Sleduj svoj postup, plň zberateľské výzvy a objav dáta, z ktorých tento svet vznikol.');html+=`<div class="grid"><article class="card"><h3>Tvoja stopa v galaxii</h3><p>Obnovené svety: ${state.restored.length} / 10<br>Nazbierané suroviny: ${state.gathered}<br>Porazení nepriatelia: ${state.kills}<br>Vyrobené materiály: ${state.crafted}<br>Skúsenosti: ${state.xp}</p></article><article class="card"><h3>Výzva ${state.challenge+1} · Zberateľ</h3><p>Nazbieraj celkovo ${goal} surovín.<br>Postup: ${Math.min(goal,state.gathered)} / ${goal}<br>Odmena: 50 mincí.</p>${button('Vyzdvihnúť odmenu','challenge',state.gathered<goal)}</article></div><div class="card" style="margin-top:12px"><h3>Prestige · ${state.prestige} hviezd</h3><p>Po obnove všetkých desiatich svetov môžeš začať novú výpravu. Planéty, batoh a vybavenie sa resetujú. Každá prestige hviezda pridá trvalých 10 % k zberu a útoku.</p>${button('Nová výprava s prestige →','prestige-confirm',state.restored.length<10,'')}</div><div class="actions">${button('Archív 4 907 objektov','catalog',false,'')}${button('Export uloženia','export',false,'')}${button('Import uloženia','import',false,'')}${button('Návod','help',false,'')}</div>`;}
if(panel==='catalog'){html=heading('DÁTA ZA DOBRODRUŽSTVOM','Archív expedície',`${D.catalog.length.toLocaleString('sk')} dekódovaných objektov · ${D.resources.length} surovín · ${D.enemies.length} nepriateľov · ${D.recipes.length} receptov. Rozbaľ záznam a pozri jeho pôvodné hodnoty.`);html+='<input id="catalog-search" placeholder="Hľadať názov, kategóriu alebo surovinu…" aria-label="Vyhľadať v archíve"><div id="catalog-results" class="catalog"></div><p class="subtitle">Archív zachováva pôvodné dáta. Nie každý objekt je aktívnym prvkom tejto HTML5 rekonštrukcie. Poškodené číselné enumy sa nepoužívajú.</p>';}
if(panel==='help'){html=heading('VITAJ, PRIESKUMNÍK','Ako zachrániť svet','Začni pri stromoch, nazbieraj 20 dreva a obnov jadro Hadesu. Na Gaii objavíš kameň, kryštály aj nepriateľov.');html+='<div class="grid"><article class="card"><h3>Pohyb a akcie</h3><p>WASD / šípky: pohyb<br>Drž medzerník: zber alebo útok<br>E: jadro alebo tábor v blízkosti<br>Na dotyku: ľavý joystick a pravé tlačidlá<br>Esc: zavrieť menu / pauza</p></article><article class="card"><h3>Cesta k ďalšej planéte</h3><p>1. Zbieraj uvedené materiály.<br>2. Pri jadre stlač E a obnov svet.<br>3. Cestuj cez hviezdnu mapu.<br>4. Vyrábaj dosky a oceľ, vylepšuj výbavu.<br>5. Obnov všetkých 10 planét.</p></article></div><div class="notice" style="margin-top:15px">Hra je nová HTML5 interpretácia statického REA reportu. Pôvodné modely a vykonateľný kód tu nie sú. Planéty, stropy, atribúty nástrojov a základné recepty pochádzajú z reportu; mapa, grafika, bojové vyváženie a postup sú doplnené. Úplné zdrojové dáta nájdeš v archíve.</div><div class="actions">'+button('Otvoriť archív','catalog',false,'')+button('Export uloženia','export',false,'')+'</div>';}
if(panel==='prestige-confirm'){html=heading('NOVÁ KAPITOLA','Začať ďalšiu výpravu?','Táto akcia resetuje planéty, materiály, nástroje aj domov. Získaš jednu trvalú prestige hviezdu. Najskôr si môžeš exportovať aktuálne uloženie.');html+=button('Exportovať uloženie','export',false,'')+' '+button('Začať novú výpravu','prestige');}
if(panel==='pause'){html=heading('CHVÍĽA MEDZI HVIEZDAMI','Výprava pozastavená','Svet počká. Výroba v rafinériách sa dokončuje podľa skutočného času.');html+=button('Pokračovať →','resume')+'<div class="actions">'+button('Export uloženia','export',false,'')+button('Návod','help',false,'')+'</div>';}
$('#panel-content').innerHTML=html;if(panel==='catalog'){catalog('');$('#catalog-search').addEventListener('input',e=>catalog(e.target.value));}}
function catalog(query){const terms=query.toLowerCase().trim().split(/\s+/);const matches=D.catalog.filter(x=>terms.every(t=>(x.name+' '+x.category).toLowerCase().includes(t)));$('#catalog-results').innerHTML=`<p class="subtitle">${matches.length} výsledkov · zobrazených prvých 80</p>`+matches.slice(0,80).map(x=>`<details><summary>${esc(x.name)} <small style="color:#8fa599">${esc(x.category)}</small></summary><pre>${esc(JSON.stringify(x.data,null,2))}</pre></details>`).join('');}
function exportSave(){save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='planetarna-vyprava-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Uloženie exportované.');}
function doAction(a){const [kind,arg]=a.split(':');if(kind==='travel'){if(C.travel(state,Number(arg))){scene=C.world(state.planet);Object.assign(player,state.position,{vx:0,vy:0});particles=[];floaters=[];closePanel();notify('Vitaj na planéte '+D.planets[state.planet].title);sound(700,.3);}}else if(kind==='upgrade'){if(C.upgrade(state,arg)){notify(C.name(arg)+' vylepšená.');sound(700,.2);}}else if(kind==='craft'){if(C.craft(state,arg))notify('Výroba spustená.');}else if(kind==='restore'){if(C.restore(state)){burst(1,-3,'#eaffad',50);sound(900,.6);notify(state.restored.length===10?'Víťazstvo! Všetkých desať svetov opäť žiari.':'Planéta obnovená! Nová cesta je otvorená.');}}else if(kind==='map'){panel='map';}else if(kind==='sell'){if((state.inventory[arg]||0)>=1){state.inventory[arg]--;C.grant(state,'Coin',5);}}else if(kind==='build'){if(state.home<5&&C.pay(state,{Plank:10*(state.home+1),Steel:8*(state.home+1)})){state.home++;state.hp+=20;notify('Domov rozšírený.');}}else if(kind==='worker'){if(state.workers<5&&C.pay(state,{Coin:100*(state.workers+1),Plank:10})){C.production(state);state.workers++;state.workerTime=Date.now();notify('Pomocník sa pridal k výprave.');}}else if(kind==='refinery-upgrade'){if(state.refineryLevel<20&&C.pay(state,{Coin:1000*(state.refineryLevel+1)}))state.refineryLevel++;}else if(kind==='challenge'){if(state.gathered>=100*(state.challenge+1)){C.grant(state,'Coin',50);state.challenge++;sound(750,.2);}}else if(kind==='prestige'){if(state.restored.length===10){let p=state.prestige+1,s=state.sound;state=C.fresh();state.prestige=p;state.sound=s;state.started=true;scene=C.world(0);Object.assign(player,state.position,{vx:0,vy:0});closePanel();notify('Prestige '+p+' · nová výprava začína.');}}else if(kind==='export'){exportSave();}else if(kind==='import'){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>200000)throw Error();const raw=JSON.parse(await file.text());if(raw.version!==1||!raw.inventory||!raw.tools)throw Error();state=C.normalize(raw);scene=C.world(state.planet);Object.assign(player,state.position,{vx:0,vy:0});save();closePanel();updateHUD();notify('Uloženie načítané.');}catch{notify('Tento súbor nie je platné uloženie hry.');}};input.click();}else if(kind==='resume'){paused=false;closePanel();}else if(['catalog','help','prestige-confirm'].includes(kind))panel=kind;save();updateHUD();if(panel)drawPanel();}
$('#panel-content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)doAction(b.dataset.action);});
document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>openPanel(b.dataset.panel));$('#map-button').onclick=()=>openPanel('map');$('#modal .close').onclick=()=>{paused=false;closePanel();};$('#modal').onclick=e=>{if(e.target===$('#modal')){paused=false;closePanel();}};$('#help').onclick=()=>openPanel('help');$('#pause').onclick=()=>{paused=!paused;if(paused)openPanel('pause');else closePanel();};$('#sound').onclick=()=>{state.sound=!state.sound;$('#sound').style.color=state.sound?'#d9f080':'';$('#sound').setAttribute('aria-label',state.sound?'Vypnúť zvuk':'Zapnúť zvuk');sound();save();};$('#start').textContent=state.started?'Pokračovať vo výprave →':'Začať výpravu →';$('#start').onclick=()=>{started=true;state.started=true;$('#intro').hidden=true;const done=C.production(state);save();notify(done.length?'Vitaj späť! Výroba bola dokončená.':'Zbieraj drevo pri stromoch · podrž medzerník.');};
addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','w','a','s','d'].includes(key))e.preventDefault();if(!started)return;if(key==='escape'){if(panel){paused=false;closePanel();}else{paused=true;openPanel('pause');}return;}if(panel||e.repeat)return;const menus={i:'inventory',u:'workshop',r:'refinery',h:'home',j:'journal',m:'map'};if(menus[key])openPanel(menus[key]);else if(key==='e')interact();else {keys.add(key);if(key===' ')act();}});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>{keys.clear();stick={x:0,y:0};actionHeld=false;save();});document.addEventListener('visibilitychange',()=>{keys.clear();stick={x:0,y:0};actionHeld=false;if(document.hidden)save();});addEventListener('beforeunload',save);
const joy=$('#joystick');let joyPointer=null;function joyMove(e){if(e.pointerId!==joyPointer)return;const r=joy.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,m=Math.max(35,Math.hypot(dx,dy));stick={x:dx/m,y:dy/m};joy.firstElementChild.style.transform=`translate(${stick.x*30}px,${stick.y*30}px)`;}joy.onpointerdown=e=>{joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);joyMove(e);};joy.onpointermove=joyMove;joy.onpointerup=joy.onpointercancel=()=>{joyPointer=null;stick={x:0,y:0};joy.firstElementChild.style.transform='';};$('#touch-action').onpointerdown=e=>{actionHeld=true;if(started&&!panel&&!paused)act();e.target.setPointerCapture(e.pointerId);};$('#touch-action').onpointerup=$('#touch-action').onpointercancel=()=>actionHeld=false;$('#touch-interact').onclick=()=>{if(started&&!panel)interact();};
setInterval(()=>{if(!started)return;const done=C.production(state);if(done.length){notify('Výroba dokončená: '+done.map(j=>j.amount+' '+C.name(j.product)).join(', '));save();if(panel==='refinery')drawPanel();}if(panel==='refinery')document.querySelectorAll('[data-job]').forEach(el=>{const jobs=state.jobs.filter(j=>j.product===el.dataset.job);el.textContent=jobs.length?jobs.length+' vo fronte · '+Math.max(0,Math.ceil((jobs[0].end-Date.now())/1000))+' s':'Pripravené na výrobu';});},1000);
function loop(now){const dt=Math.min((now-last)/1000,.05);last=now;tick(dt);render();requestAnimationFrame(loop);}updateHUD();requestAnimationFrame(loop);
